# Generated by build.py from recipe.yml for recipe pop3-peek-at-headers-with-top. Do not edit.
set -e
cd "$(dirname "$0")"
cat > order1.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 1 shipped

Your first order is on its way.
It left the warehouse this morning.
Track it with code 1111.
EOF
cat > order2.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 2 delayed

Your second order is late.
A part is out of stock.
We will write again within a week.
EOF
cat > order3.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 3 shipped

Your third order is on its way.
It left the warehouse this morning.
Track it with code 3333.
EOF
surl --mail-domain example.com --mailbox ann@example.com:annpass --mailbox shop@example.com:shoppass smtp://127.0.0.1:8080/ pop3://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-3].eml" smtp://127.0.0.1:8080/example.com
curl -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "LIST 3" pop3://127.0.0.1:8081/
curl -u ann@example.com:annpass -X UIDL pop3://127.0.0.1:8081/ --next -u ann@example.com:annpass -X "TOP 2 0" pop3://127.0.0.1:8081/
kill $(jobs -p)
